def trace(func):
    def wrapper(*args, **kwargs):
        print("args:", args)
        print("kwargs:", kwargs)
        return func(*args, **kwargs)
    return wrapper

@trace
def greet(name, punctuation="!"):
    return f"Hello, {name}{punctuation}"

print(greet("Ada", punctuation="."))

from datetime import datetime

def stamp_bad(created_at=datetime.now()):
    return created_at

def stamp_good(created_at=None):
    if created_at is None:
        created_at = datetime.now()
    return created_at

print(stamp_bad() is stamp_bad())
print(stamp_good() == stamp_good())

