def parse_and_use(text):
    try:
        value = int(text)
    except ValueError:
        print("invalid")
    else:
        print(100 // value)
    finally:
        print("cleanup")

parse_and_use("4")
parse_and_use("bad")

class ConfigMissingError(RuntimeError):
    pass

def require_key(config, key):
    try:
        return config[key]
    except KeyError as exc:
        raise ConfigMissingError(f"Missing config key: {key}") from exc

require_key({}, "token")

